namespace SnapGrab {
 internal static partial class UserGuide {
  private static readonly HelpTopic[] EnglishTopics = {
   new HelpTopic("Image editing", "Configure a separate Images Edits endpoint, image model and API key. Select a region, protect important content with the brush, then use Remove text, Replace text or Edit image. Upload preview includes up to 32 source pixels around the region; green shading is only a permission preview. Requests may cost money and are never automatically retried. Review the generated result before applying. Outside and protected pixels stay original. Replace text repairs the background through the service and draws new text locally using the current size and color. Font matching is manual; text may clip. One undo restores the previous source and annotations. Real paid-service output quality is not yet verified."),
   new HelpTopic("AI region", "Click AI region and drag on the image. A cyan outline marks the selected source pixels and is never exported. Redraw to adjust; Esc or Clear AI region returns to whole-image mode. Only the local PNG and current request are sent, without old conversation. The upload size limit still applies. Review numbered targets and recognized text, select operations, and confirm. If targets are wrong, cancel and redraw. Local edits stay clipped to this region, including undo/redo. Crop operations are rejected in regional mode. This version supports annotation, redaction and OCR commands; generative edits use the separate image-edit workflow."),
   new HelpTopic("Getting started", "SnipRefine " + Program.VersionText + "\r\nCapture, annotate and use AI assistance. Ctrl+Alt+A opens an adjustable selection; confirm to edit. Ctrl+Alt+S saves a quick selection immediately. PrintScreen captures the combined desktop. Screenshot and manual editing work without an API key."),
   new HelpTopic("Capture and save", "Drag inside a selection to move it; drag edges or corners to resize. Enter or double-click confirms; Esc cancels. Ctrl+S saves and keeps the editor open. Ctrl+Shift+S opens Save As. Ctrl+C copies. Save failures retain the editor for retry. Copy and save closes the editor and writes the image in the background."),
   new HelpTopic("Editing", "Select a drawing tool, color and width, then drag. Ctrl+Z undoes; Ctrl+Y redoes. Select annotations to move, resize or delete them. Enter commits text; Esc cancels text. Ctrl+wheel zooms; Space+drag pans. Use solid redaction for private content and inspect the final image."),
   new HelpTopic("AI configuration", "Open Settings > AI assistant. Choose a provider, enter your key and model, test connection and save. A successful text connection does not prove image support: test vision separately. Screenshot understanding, OCR and AI annotation need an image-capable model. Provider permissions determine available models."),
   new HelpTopic("AI edits and OCR", "AI edits send the current image and instruction to the selected service. Supported operations include annotation, solid redaction, crop and OCR. Use the separate image-edit service for generated pixel edits. Review proposed edits before applying; one batch is one undo step. AI does not automatically save or copy. Cancel rejects late replies."),
   new HelpTopic("Privacy", "Manual screenshot editing stays local. AI requests send their image and text to the configured endpoint. Automatic attachment of the latest screenshot is off by default. API keys use Windows current-user DPAPI encryption. Never publish configuration, keys, logs or private screenshots. Blur is not secure redaction. Providers may charge for requests, including cancelled requests."),
   new HelpTopic("Display diagnostics", "Settings > Appearance > Display diagnostics lists OS, runtime, monitor bounds and DPI. It contains no API keys, endpoint addresses or screenshots. DPI may fall back to 96 if the system API is unavailable. Mixed-DPI multi-monitor behavior still requires Windows real-device acceptance testing."),
   new HelpTopic("Language preview", "Choose English (Preview) in Settings > Appearance and restart. Core controls and this help are translated. Some detailed status, error messages and configuration descriptions remain Chinese. User text, model IDs and AI replies are preserved.")
  };
 }
}
